// App.tsx - Dual-mode Elder Companion App
import React, { useState } from 'react';
import { OnboardingFlow } from './components/OnboardingFlow';
import { ConversationMode } from './components/ConversationMode';
import './App.css';

type AppMode = 'onboarding' | 'conversation';

function App() {
  const [mode, setMode] = useState<AppMode>('onboarding');
  const [elderProfile, setElderProfile] = useState<any>(null);

  const handleOnboardingComplete = (profile: any) => {
    console.log('Onboarding complete with profile:', profile);
    setElderProfile(profile);
    setMode('conversation');
  };

  // For development: quick mode switch
  const toggleMode = () => {
    if (mode === 'onboarding') {
      setElderProfile({
        cognitive_comfort: 'intermediate',
        personality: 'independent',
        tone_preference: 'casual'
      });
      setMode('conversation');
    } else {
      setMode('onboarding');
    }
  };

  return (
    <div className="App">
      {/* Development mode switcher */}
      <button
        className="dev-mode-toggle"
        onClick={toggleMode}
        style={{
          position: 'fixed',
          top: '10px',
          right: '10px',
          zIndex: 9999,
          padding: '8px 16px',
          background: '#667eea',
          color: 'white',
          border: 'none',
          borderRadius: '8px',
          cursor: 'pointer',
          fontSize: '12px'
        }}
      >
        🔄 Switch to {mode === 'onboarding' ? 'Chat' : 'Onboarding'}
      </button>

      {mode === 'onboarding' ? (
        <OnboardingFlow />
      ) : (
        <ConversationMode elderProfile={elderProfile} />
      )}
    </div>
  );
}

export default App;
